/**
 * الحصول على اختبار فصل محدد
 * @param {number|string} currId - معرّف المادة
 * @param {number|string} chapterId - معرّف الفصل
 * @returns {object|null} كائن الاختبار والأسئلة
 */
window.getChapterQuiz = function(currId, chapterId) {
  if (!window.CHAPTER_QUIZZES) return null;
  const cId = Number(currId);
  const chId = Number(chapterId);
  const subj = window.CHAPTER_QUIZZES[cId];
  if (!subj) return null;
  if (subj[chId]) return subj[chId];
  
  // بحث تقريبي في حال كان المعرف نصياً أو قريباً
  const keys = Object.keys(subj);
  for (const k of keys) {
    if (String(k) === String(chapterId)) return subj[k];
  }
  return null;
};

/**
 * الحصول على كافة اختبارات الفصول لمادة دراسية محددة
 * @param {number|string} currId - معرّف المادة
 * @returns {Array} قائمة اختبارات فصول المادة
 */
window.getSubjectAllQuizzes = function(currId) {
  if (!window.CHAPTER_QUIZZES) return [];
  const cId = Number(currId);
  const subj = window.CHAPTER_QUIZZES[cId];
  if (!subj) return [];
  return Object.keys(subj).map(k => ({
    chapterId: Number(k),
    ...subj[k]
  }));
};

/**
 * توليد أسئلة عشوائية شاملة لمادة معينة من مختلف فصولها
 * @param {number|string} currId - معرّف المادة
 * @param {number} count - عدد الأسئلة المطلوب
 * @returns {Array} مصفوفة الأسئلة
 */
window.getRandomQuestionsForCurriculum = function(currId, count = 10) {
  const quizzes = window.getSubjectAllQuizzes(currId);
  if (!quizzes || quizzes.length === 0) return [];
  let allPool = [];
  quizzes.forEach(q => {
    if (Array.isArray(q.questions)) {
      allPool = allPool.concat(q.questions);
    }
  });
  if (allPool.length === 0) return [];
  
  // خلط عشوائي (Fisher-Yates)
  const shuffled = [...allPool];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled.slice(0, count);
};
